SELECT c.id, c.parent_id AS parentId, c.designation AS name, c.search_count AS searchCount, c.sort, c.create_time AS createTime, CONCAT(#{imgBaseUrl}, im.stored_name) AS imageUrl FROM category c LEFT JOIN image_management im ON c.image_id = im.id
AND c.id = #{query.id}
AND c.table_name = #{query.tableName}
AND c.parent_id IS NULL
AND c.parent_id = #{query.parentId}
AND c.designation LIKE CONCAT('%', #{query.name}, '%')
ORDER BY c.sort ASC, c.create_time ASC
